 const surface=document.createElement('div');surface.className='am-surface iso';surface.dataset.theme='light';root.append(surface);
 surface.innerHTML=`<nav class="am-chapters" aria-label="Three experiments"><span data-chapter="personal">01 Your afternoon</span><span data-chapter="budget">02 Leah’s £10</span><span data-chapter="tighter">03 Change the budget</span></nav>
 <section class="am-experiment"><div class="am-task"><span id="am-step" class="am-kicker"></span><h2 id="am-question" tabindex="-1"></h2><p id="am-guidance"></p></div>
 <div id="am-ranking" class="am-ranking" hidden></div><div class="am-plate"><div class="am-corners"><span>FIG. 01 / ONE TICKET</span><button id="am-theme" aria-label="Switch to dark machine">Dark / light</button></div><div id="am-world">${ART.svg}</div><div class="am-corners am-bottom"><span id="am-machine-hint"></span><strong id="am-machine-readout" data-readout></strong></div></div>
 <div id="am-options" class="am-options"></div><div id="am-extra"></div><p id="am-caption" class="am-caption" role="status"></p></section>`;
 controlsRoot.innerHTML=`<div class="am-actions"><button id="am-back" class="am-text">Change my choice</button><div><button id="am-commit" class="am-primary" hidden>Dock my ticket →</button><span id="am-check-slot"></span></div></div>
 <div id="am-comparison" class="am-comparison" hidden></div><section id="am-result" class="am-result" hidden><span id="am-result-kicker" class="am-kicker"></span><h2 id="am-result-title" tabindex="-1"></h2><div id="am-feedback-slot"></div><p id="am-explanation"></p><button id="am-next" class="am-primary" hidden></button></section>
 <div class="am-bottom-controls"><button id="am-help" class="am-text">A hint, please</button><span id="am-reset-slot"></span></div><p id="am-help-text" hidden></p><details class="am-notes"><summary>Try it with a real choice</summary><p>Think of something you want to do this weekend. If you could not do it, what would you do instead? What would you miss about that alternative?</p><p>Different people value different things. This machine compares only the complete, mutually exclusive plans shown here. It does not measure happiness or prove mastery.</p></details>
 <p class="am-credit">Built with <a href="https://github.com/wheresryan22/anatomy">Anatomy</a> · MIT © 2026 Ryan · <a href="assets/anatomy-license.txt">License</a></p>`;
 const $=id=>app.querySelector('#'+id),check=$('check'),feedback=$('feedback'),reset=$('reset'),readout=$('readout');
 const original={check:check.parentNode,feedback:feedback.parentNode,reset:reset.parentNode};
 $('am-check-slot').append(check);$('am-feedback-slot').append(feedback);$('am-reset-slot').append(reset);reset.textContent='Start from the beginning';readout.classList.add('sr-only');
 app.querySelector('.brand').innerHTML='<span>◈</span> THE CHOICE WORKSHOP';app.querySelector('.topbar .pill').textContent='An Anatomy experiment';
 let observed=null,phaseKey='',revealed=false,disposed=false,frame=0,last=0,visible=true;
 let at={u:0,v:0},target={u:0,v:0},gate=[0,0,0],gateTargets=[0,0,0];
 const still=matchMedia('(prefers-reduced-motion: reduce)'),carriage=$('am-carriage');
 const ids=()=>observed?.round==='personal'?['robot','film','park']:['robot','film','garden'];
 const toScreen=(u,v,z)=>[0,1].map(i=>ART.basis[0][i]*u+ART.basis[1][i]*v+ART.basis[2][i]*z);
 function draw(){
  const [x,y]=toScreen(at.u,at.v,0);carriage.setAttribute('transform',`translate(${x} ${y})`);
  surface.querySelectorAll('[data-gate]').forEach((g,i)=>{const [x,y]=toScreen(0,0,gate[i]);g.setAttribute('transform',`translate(${x} ${y})`);});
 }
 function stop(){if(frame)cancelAnimationFrame(frame);frame=0;last=0;}
