  at.u+=(target.u-at.u)*rate;at.v+=(target.v-at.v)*rate;for(let i=0;i<3;i++)gate[i]+=(gateTargets[i]-gate[i])*rate;
  const unsettled=Math.abs(target.u-at.u)>.025||Math.abs(target.v-at.v)>.025||gate.some((n,i)=>Math.abs(n-gateTargets[i])>.025);
