  $('am-result').hidden=true;$('am-next').hidden=true;if(changedRound)$('am-help-text').hidden=true;
  $('am-machine-hint').textContent=hasChoice?'ONE TICKET DOCKED / OTHER BAYS UNUSED':'TAP A BAY / PREVIEW, THEN DOCK';
  $('am-machine-readout').textContent=personal?'2 hours · 1 choice':'£'+o.cash+' originally · £'+o.leftCash+' left';
  $('am-caption').textContent=o.alternative?'Solid ticket = chosen plan. Outlined bay = your proposed next-best alternative. It is a comparison, not a second purchase.':hasChoice?'The ticket can enter only one bay. What is the best opportunity left behind?':o.candidate?'Previewing '+o.options.find(n=>n.id===o.candidate).title.toLowerCase()+'. Press “Dock my ticket” to confirm.':'One ticket. Three possibilities. Your first tap is only a preview.';
  const index=ids().indexOf(o.selected||o.candidate),u=index<0?0:ART.bayCenters[index];target={u,v:o.selected?-30:0};gateTargets=ids().map(id=>id===o.selected?18:0);
